from pathlib import Path
html = Path(r'xmfls-osm-model\src\index.html').read_text(encoding='utf-8')
js = '''<style>#dbg{position:fixed;z-index:99;left:10px;bottom:10px;background:#000;color:#0f0;font:11px monospace;padding:8px;white-space:pre}</style>
<script>setTimeout(function(){var M=window.__MODEL; if(!M)return; var S=M.sun; S.position.set(120,220,110); S.castShadow=true; S.shadow.bias=0; S.shadow.normalBias=0.01; S.shadow.camera.left=-900; S.shadow.camera.right=900; S.shadow.camera.top=900; S.shadow.camera.bottom=-900; S.shadow.camera.near=0.5; S.shadow.camera.far=2000; S.shadow.camera.updateProjectionMatrix(); M.renderer.shadowMap.type=THREE.BasicShadowMap; M.renderer.shadowMap.needsUpdate=true; M.scene.background=new THREE.Color(0x607080); var cube=new THREE.Mesh(new THREE.BoxGeometry(35,55,35),new THREE.MeshStandardMaterial({color:0xcc4433,roughness:.7})); cube.position.set(0,27.5,0); cube.castShadow=true; cube.receiveShadow=true; M.scene.add(cube); M.view.goalTarget.set(10,8,-10); M.view.goalRadius=260; M.view.goalPhi=1.18; M.view.goalTheta=.72; M.view.auto=false; var d=document.createElement('div'); d.id='dbg'; d.textContent='shadow '+S.shadow.mapSize.x+' near '+S.shadow.camera.near+' far '+S.shadow.camera.far+' bias '+S.shadow.bias; document.body.appendChild(d);},700);</script>'''
Path(r'xmfls-osm-model\src\inspect_debug2.html').write_text(html.replace('</body>', js + '</body>'), encoding='utf-8')
print('ok')
